1458.docs:
Try to get the underlying type `T`.

Same as [`downcast`] except it doesn't consume `self` and hence requires
`T: TryFrom<&Value<_>>`.

# Examples

```
use zvariant::{Error, Result, Value};

fn value_vec_to_type_vec<'a, T>(values: &'a Vec<Value<'a>>) -> Result<Vec<&'a T>>
where
    &'a T: TryFrom<&'a Value<'a>>,
    <&'a T as TryFrom<&'a Value<'a>>>::Error: Into<Error>,
{
    let mut res = vec![];
    for value in values.into_iter() {
        res.push(value.downcast_ref()?);
    }

    Ok(res)
}

// Let's try u32 values first
let v = vec![Value::U32(42), Value::U32(43)];
let v = value_vec_to_type_vec::<u32>(&v).unwrap();
assert_eq!(*v[0], 42);
assert_eq!(*v[1], 43);

// Now try Value values
let v = vec![Value::new(Value::U32(42)), Value::new(Value::U32(43))];
let v = value_vec_to_type_vec::<Value>(&v).unwrap();
assert_eq!(*v[0], Value::U32(42));
assert_eq!(*v[1], Value::U32(43));
```

[`downcast`]: enum.Value.html#method.downcast

2215.docs:
A wrapper to deserialize a value to `T: Type + serde::Deserialize`.

When the type of a value is well-known, you may avoid the cost and complexity of wrapping to a
generic [`enum@crate::Value`] and instead use this wrapper.

```
# use zvariant::{to_bytes, serialized::Context, as_value::{Deserialize, Serialize}, LE};
#
# let ctxt = Context::new_dbus(LE, 0);
# let array = [0, 1, 2];
# let v = Serialize(&array);
# let encoded = to_bytes(ctxt, &v).unwrap();
let decoded: Deserialize<[u8; 3]> = encoded.deserialize().unwrap().0;
# assert_eq!(decoded.0, array);
```

1907.docs:
The signature for the implementing type, in parsed format.

# Example

```
use std::collections::HashMap;
use zvariant::{Type, signature::{Child, Signature}};

assert_eq!(u32::SIGNATURE, &Signature::U32);
assert_eq!(String::SIGNATURE, &Signature::Str);
assert_eq!(
    <(u32, &str, u64)>::SIGNATURE,
    &Signature::static_structure(&[&Signature::U32, &Signature::Str, &Signature::U64]),
);
assert_eq!(
    <(u32, &str, &[u64])>::SIGNATURE,
    &Signature::static_structure(&[
        &Signature::U32,
        &Signature::Str,
        &Signature::Array(Child::Static { child: &Signature::U64 }),
    ]),
);
assert_eq!(
    <HashMap<u8, &str>>::SIGNATURE,
    &Signature::static_dict(&Signature::U8, &Signature::Str),
);
```

